def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeated horizontal color strip (the palette), replicated in
    # at least two adjacent rows. Prefer the largest such solid rectangle.
    best = None
    for top in range(h):
        for left in range(w):
            if grid[top][left] == 0:
                continue
            for right in range(left + 1, w + 1):
                seq = grid[top][left:right]
                if 0 in seq:
                    break
                bottom = top + 1
                while bottom < h and grid[bottom][left:right] == seq:
                    bottom += 1
                height = bottom - top
                area = len(seq) * height
                if height >= 2 and (best is None or area > best[0]):
                    best = (area, top, left, bottom, right, seq[:])
